def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Top-edge markers send lines downward, stopping where a matching
    # marker on a side edge sends a horizontal line toward them.
    for c, color in enumerate(grid[0]):
        if color == 0:
            continue
        endpoints = [
            r for r in range(1, h)
            if (grid[r][0] == color or grid[r][w - 1] == color)
        ]
        stop = min(endpoints) if endpoints else h - 1
        for r in range(stop + 1):
            out[r][c] = color

    # Matching markers on the left and right edges extend to the
    # column of their top-edge marker.
    top_cols = {}
    for c, color in enumerate(grid[0]):
        if color != 0:
            top_cols.setdefault(color, c)

    for r in range(h):
        for edge_col in (0, w - 1):
            color = grid[r][edge_col]
            if color != 0 and color in top_cols:
                c = top_cols[color]
                for x in range(min(edge_col, c), max(edge_col, c) + 1):
                    out[r][x] = color

    return out
